<?php
require_once __DIR__ . '/includes/auth.php'; requireLogin(); $userId=(int)$_SESSION['user_id']; $pageTitle='Manual Deposit'; $error='';
if($_SERVER['REQUEST_METHOD']==='POST'){ if(!verifyCsrf($_POST['csrf_token']??null))$error='Your session expired.'; else { $amount=(float)post('amount'); $method=trim((string)post('payment_method')); $reference=trim((string)post('payment_reference')); if($amount<100)$error='Minimum demo deposit is PKR 100.'; elseif($method==='')$error='Select a payment method.'; else { $s=getDB()->prepare('INSERT INTO deposits(user_id,amount,payment_method,payment_reference,status) VALUES(?,?,?,?,"pending")'); $s->execute([$userId,$amount,$method,$reference]); flash('success','Deposit request submitted for admin review.'); redirect(appUrl('deposit.php')); } } }
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= e($pageTitle) ?> - <?= e(APP_NAME) ?></title><link rel="stylesheet" href="assets/css/style.css"><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css"></head><body><?php include __DIR__.'/includes/header.php'; ?><?php include __DIR__.'/includes/sidebar.php'; ?><main class="main-content"><div class="page-title"><span class="eyebrow">SIMULATED PAYMENT</span><h1>Confirm deposit</h1><p class="muted">No external payment is made. Enter any demo reference for testing.</p></div><section class="panel narrow-panel"><?php if($error): ?><div class="alert error"><?= e($error) ?></div><?php endif; ?><form method="post" class="form-stack"><?= csrfField() ?><label>Amount (PKR)<input type="number" name="amount" min="100" step="0.01" required></label><label>Payment method<select name="payment_method" required><option value="">Choose method</option><option>JazzCash</option><option>EasyPaisa</option><option>Bank transfer</option><option>Demo wallet</option></select></label><label>Payment reference<input name="payment_reference" maxlength="100" placeholder="e.g. DEMO-12345"></label><button class="btn primary full" type="submit">Submit deposit request</button></form></section></main><?php include __DIR__.'/includes/bottom-nav.php'; ?><?php include __DIR__.'/includes/footer.php'; ?><script src="assets/js/app.js"></script></body></html>
